-- id=64  الأرقم بن أبي الأرقم
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 64;

BEGIN;

UPDATE public.stories
SET source_codes = 'د ب ع',
    content_ar = 'الأرقم بن أبي الأرقم
واسم أبي الأرقم عبد مناف بن أسد بن عبد الله بن عمرو بن مخزوم القرشي المخزومي وأمه أميمة بنت عبد الحارث وقيل اسمها تماضر بنت حذيم من بني سهم وقيل اسمها صفية بنت الحارث بن خالد بن عمير بن غبشان الخزاعية يكنى أبا عبد الله كان من السابقين الأولين إلى الإسلام أسلم قديما قيل كان ثاني عشر وكان من المهاجرين الأولين وشهد بدرا ونفله رسول الله صلى الله عليه وسلم منها سيفا واستعمله على الصدقات وهو الذي استخفى رسول الله في داره وهي في أصل الصفا والمسلمون معه بمكة لما خافوا المشركين فلم يزالوا بها حتى كملوا أربعين رجلا وكان آخرهم إسلاما عمر بن الخطاب فلما كملوا به أربعين خرجوا وقال أبو عمر ذكر ابن أبي خيثمة أن أبا الأرقم والد الأرقم أسلم أيضا وروي من بني مخزوم وهذا غلط قال وغلط أبو حاتم الرازي وابنه فجعلاه والد عبد الله بن الأرقم وليس كذلك فإن عبد الله بن الأرقم زهري فإنه عبد الله بن الأرقم بن عبد يغوث بن وهب بن عبد مناف بن زهرة وكان عبد الله على بيت المال لعثمان بن عفان رضي الله عنه وروى يحيى بن عمران بن عثمان بن عفان بن الأرقم الأرقمي عن عمة عبد الله بن عثمان وعن أهل بيته عن جده عثمان بن الأرقم عن الأرقم أنه تجهز يريد البيت المقدس فلما فرغ من جهازه جاء إلى النبي صلى الله عليه وسلم يودعه فقال ما يخرجك أحاجة أم تجارة قال لا يا رسول الله بأبي أنت وأمي ولكني أريد الصلاة في بيت المقدس فقال رسول الله عليه السلام صلاة في مسجدي هذا خير من ألف صلاة فيما سواه من المساجد إلا المسجد الحرام قال فجلس الأرقم أخبرنا أبو ياسر عبد الوهاب بن هبة الله بن أبي حبة بإسناده إلى عبد الله بن أحمد بن حنبل قال حدثني أبي حدثنا عباد بن عباد المهلبي عن هشام بن زياد عن عثمان بن الأرقم بن أبي الأرقم المخزومي عن أبيه وكان من أصحاب النبي صلى الله عليه وسلم قال إن الذي يتخطى رقاب الناس يوم الجمعة ويفرق بين الاثنين بعد خروج الإمام كالجار قضبه في النار وقال عثمان بن الأرقم توفي أبي الأرقم سنة ثلاث وخمسين وهو ابن ثلاث وثمانين سنة وقيل توفي سنة خمس وخمسين وهو ابن بضع وثمانين سنة وأوصى أن يصلي عليه سعد بن أبي وقاص وكان سعد بالعقيق فقال مروان يحبس صاحب رسول الله لرجل غائب وأراد الصلاة عليه فأبى عبيد الله بن الأرقم ذلك على مروان وقامت معه بنو مخزوم ووقع بينهم كلام ثم جاء سعد فصلى عليه وقد ذكر أبو نعيم أنه توفي يوم مات أبو بكر الصديق والأول 
أصح ودفن بالبقيع أخرجه ثلاثتهم'
WHERE id = 64
  AND content_ar LIKE '(د ب ع) الأرقم بن أب%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 64;

-- id=65  حمزة بن عبد المطلب
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 65;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'حمزة ابن عبد المطلب بن هاشم بن عبد مناف بن قصي أبو يعلى وقيل أبو عمارة كنى بابنيه يعلى وعمارة وأمه هالة بنت وهيب بن عبد مناف بن زهرة وهي ابنة عم آمنة بنت وهب أم النبي صلى الله عليه وسلم وهو شقيق صفية بنت عبد المطلب أم الزبير وهو عم رسول الله صلى الله عليه وسلم وأخوه من الرضاعة أرضعتهما ثويبة مولاة أبي لهب وأرضعت أبا سلمة بن عبد الأسد وكان حمزة رضي الله عنه وأرضاه أسن من رسول الله صلى الله عليه وسلم بسنتين وقيل بأربع سنين والأول أصح وهو سيد الشهداء وآخى رسول الله صلى الله عليه وسلم بينه وبين زيد بن حارثة أسلم في السنة الثانية من المبعث وكان سبب إسلامه ما أخبرنا به أبو جعفر عبيد الله بن أحمد بإسناده إلى يونس بن بكير عن محمد بن إسحاق قال إن أبا جهل اعترض رسول الله صلى الله عليه وسلم فآذاه وشتمه ونال منه ما يكره من العيب لدينه والتضعيف له فلم يكلمه رسول الله صلى الله عليه وسلم ومولاة لعبد الله بن جدعان التيمي في مسكن لها فوق الصفا تسمع ذلك ثم انصرف عنه فعمد إلى ناد لقريش عند الكعبة فجلس معهم ولم يلبث حمزة بن عبد المطلب رضي الله عنه أن أقبل متوشحا قوسه راجعا من قنص له وكان صاحب قنص يرميه ويخرج له فكان إذا رجع من قنصه لم يرجع إلى أهله حتى يطوف بالكعبة وكان إذا فعل ذلك لم يمر على ناد من قريش إلا وقف وسلم وتحدث معهم وكان أعز قريش وأشدها شكيمة وكان يومئذ مشركا على دين قومه
فلما مر بالمولاة وقد قام رسول الله صلى الله عيه وسلم فرجع إلى بيته فقالت له يا أبا عمارة لو رأيت ما لقي ابن أخيك محمد من أبي الحكم آنفا قبيل وجده هاهنا فآذاه وشتمه وبلغ منه ما يكره ثم انصرف عنه ولم يكلمه محمد فاحتمل حمزة الغضب لما أراد الله تعالى به من كرامته فخرج سريعا لا يقف على أحد كما كان يصنع يريد الطواف بالبيت معدا لأبي جهل أن يقع به فلما دخل المسجد نظر إليه جالسا في القوم فأقبل نحوه حتى إذا قام على رأسه رفع القوس فضربه بها ضربة شجه بها شجة منكرة وقامت رجال من قريش من بني مخزوم إلى حمزة لينصروا أبا جهل فقالوا ما نراك يا حمزة إلا قد صبأت فقال حمزة وما يمنعني وقد استبان لي منه ذلك أنا أشهد أنه رسول الله صلى الله عليه وسلم وأن الذي يقول الحق فوالله لا أنزع فامنعوني إن كنتم صادقين قال أبو جهل دعوا أبا عمارة فإني والله لقد سببت ابن أخيه سبا قبيحا وتم حمزة على إسلامه فلما أسلم حمزة عرفت قريش أن رسول الله صلى الله عليه وسلم قد عز وامتنع وأن حمزة سيمنعه فكفوا عن بعض ما كانوا يتناولون منه ثم هاجر إلى المدينة وشهد بدرا وأبلى فيها بلاء عظيما مشهورا قتل شيبة بن ربيعة بن عبد شمس مبارزة وشرك في قتل عتبة بن ربيعة اشترك هو وعلي رضي الله عنهما في قتله وقتل أيضا طعيمة بن عدي بن نوفل بن عبد مناف أخا المطعم بن عدي قال أبو الحسن المدايني أول لواء عقده رسول الله صلى الله عليه وسلم لحمزة بن عبد المطلب رضي الله عنه بعثه في سرية إلى سيف البحر من أرض جهينة وخالفه ابن إسحاق فقال أول لواء عقده لعبيدة بن الحارث بن المطلب وكان حمزة يعلم في الحرب بريشة نعامة وقاتل يوم بدر بين يدي رسول الله صلى الله عليه وسلم بسيفين وقال بعض أساري الكفار من الرجل المعلم بريشة نعامة قالوا حمزة رضي الله عنه قال ذاك فعل بنا الأفاعيل وشهد أحدا فقتل بها يوم السبت النصف من شوال وكان قتل من المشركين قبل أن يقتل أحدا وثلاثين نفسا منهم سباع الخزاعي قال له حمزة هلم إلي يا ابن مقطعة البظور وكانت أمه ختانة فقتله قال ابن إسحاق كان حمزة يقاتل يومئذ بسيفين فقال قائل أي أسد هو حمزة فبينما هو كذلك إذ عثر عثرة وقع منها على ظهره فانكشف الدرع عن بطنه فزرقه وحشي الحبشي مولى جبير بن مطعم بحربة فقتله ومثل به المشركون وبجميع قتلى المسلمين إلا حنظلة بن أبي عامر الراهب فإن أباه كان مع المشركين فتركوه لأجله وجعل نساء المشركين هند وصواحباتها يجد عن أنف المسلمين وآذانهم ويبقرون بطونهم وبقرت هند بطن حمزة رضي الله عنه فأخرجت كبده فجعلت تلوكها فلم تسغها فلفظتها فقال النبي صلى الله عليه وسلم لو دخل بطنها لم تمسها النار فلما شهده النبي صلى الله عليه وسلم اشتد وجده عليه وقال لئن ظفرت لأمثلن بسبعين منهم فأنزل الله سبحانه وإن عاقبتم فعاقبوا بمثل ما عوقبتم به ولئن صبرتم لهو خير للصابرين واصبر وما صبرك إلا بالله وروى أبو هريرة قال وقف رسول الله صلى الله عليه وسلم على حمزة وقد مثل به فلم ير منظرا كان أوجع لقلبه منه فقال رحمك الله أي عم فلقد كنت وصولا للرحم فعولا للخيرات وروى جابر قال لما رأى رسول الله صلى الله عليه وسلم حمزة قتيلا بكى فلما رأى ما مثل به شهق وقال لولا أن تجد صفية لتركته حتى يحشر من بطون الطير والسباع وصفية هي أم الزبير وهي أخته وروى محمد بن عقيل عن جابر قال لما سمع النبي صلى الله عليه وسلم ما فعل بحمزة شهق فلما رأى ما فعل به صعق ولما عاد النبي صلى الله عليه وسلم إلى المدينة سمع النوح على قتلى الأنصار قال لكن حمزة لا بواكي له فسمع الأنصار فأمروا نساءهم أن يندبن حمزة قبل قتلاهم ففعلن ذلك قال الواقدي فلم يزلن يبدأن بالندب لحمزة حتى الآن وقال كعب بن مالك يرثي حمزة وقيل هي لعبد الله بن رواحة

بكت عيني وحق لها بكاهاوما يغني البكاء ولا العويلعلى أسد الإله غداة قالوالحمزة ذاكم الرجل القتيلأصيب المسلمون به جميعاهناك وقد أصيب به الرسولأبا يعلى لك الأركان هدتوأنت الماجد البر الوصولعليك سلام ربك في جنانيخالطها نعيم لا يزولألا يا هاشم الأخيار صبرافكل فعالكم حسن جميلرسول الله مصطبر كريمبأمر الله ينطق إذ يقولألا من مبلغ عني لؤيافبعد اليوم دائلة تدولوقبل اليوم ما عرفوا وذاقواوقائعنا بها يشفى الغليلنسيتم ضربنا بقليب بدرغداة أتاكم الموت العجيلغداة ثوى أبو جهل صريعاعليه الطير حائمة تجولوعتبة وابنه خرا جميعاوشيبة عضه السيف الصقيلألا يا هند لا تبدى شماتالحمزة ان عركم ذليل ألا يا هند فابكي لا تمليفأنت الواله العبرى الثكول
وكان مقتل حمزة للنصف من شوال من سنة ثلاث وكان عمره سبعا وخمسين سنة على قول من يقول إنه كان أسن من رسول الله صلى الله عليه وسلم بسنتين وقيل كان عمره تسعا وخمسين سنة على قول من يقول كان أسن من رسول الله صلى الله عليه وسلم بأربع سنين وقيل كان عمره أربعا وخمسين سنة وهذا يقوله من جعل مقام النبي صلى الله عليه وسلم بمكة بعد الوحي عشر سنين فيكون للنبي صلى الله عليه وسلم اثنتان وخمسون سنة ويكون لحمزة أربع وخمسون سنة فإنهم لا يختلفون في أن حمزة أكبر من النبي صلى الله عليه وسلم أخبرنا أبو جعفر عبيد الله بن أحمد بن علي البغدادي بإسناده عن يونس بن بكير عن ابن إسحاق قال حدثني رجل من أصحابي عن مقسم وقد أدركه عن ابن عباس قال صلى رسول الله صلى الله عليه وسلم على حمزة فكبر عليه سبع تكبيرات ثم لم يؤت بقتيل إلا صلى عليه معه حتى صلى عليه ثنتين وسبعين صلاة وأخبرنا فتيان بن محمود بن سودان أخبرنا أبو نصر أحمد بن محمد بن عبد القاهر أخبرنا أبو الحسين بن النقور أخبرنا أبو القاسم عيسى بن علي بن عيسى بن الجراح أخبرنا أبو القاسم البغوي حدثنا محمد بن جعفر الوركاني أخبرنا سعيد بن ميسرة البكري عن أنس بن مالك قال كان النبي صلى الله عليه وسلم إذا كبر على جنازة كبر عليها أربعا وأنه كبر على حمزة سبعين تكبيرة وقال أبو أحمد العسكري وكان حمزة أول شهيد صلى عليه رسول الله صلى الله عليه وسلم أخبرنا محمد بن محمد بن سرايا ابن علي الشاهد ومسمار بن أبي بكر بن العويس وغير واحد قالوا بإسنادهم إلى محمد ابن إسماعيل الجعفي الإمام حدثنا عبد الله بن يوسف أخبرنا الليث حدثني ابن شهاب عن عبد الله بن كعب بن مالك عن جابر بن عبد الله قال كان النبي صلى الله عليه وسلم يجمع بين الرجلين من قتلى أحد في قبر واحد يقول أيهم أكثر أخذا للقرآن فإذا أشير إلى أحدهما قدمه في اللحد وقال أنا شهيد على هؤلاء يوم القيامة وأمر بدفنهم في دمائهم فلم يغسلوا ودفن حمزة وابن أخته عبد الله بن جحش في قبر واحد وكفن حمزة في نمرة فكان إذا تركت على رأسه بدت رجلاه وإذا غطى بها رجلاه بدا رأسه فجعلت على رأسه وجعل على رجليه شئ من الإذخر وروى يونس بن بكير عن ابن إسحاق قال كان ناس من المسلمين قد احتملوا قتلاهم إلى المدينة ليدفنوهم بها فنهى رسول الله صلى الله عليه وسلم عن ذلك وقال ادفنوهم حيث صرعوا وقد روى عن 
حمزة عن النبي صلى الله عليه وسلم حديث أخبرنا عمر بن محمد بن طبرزد أخبرنا أبو القاسم هبة الله بن محمد بن عبد الواحد أخبرنا أبو طالب محمد بن محمد بن غيلان البزار أخبرنا أبو بكر الشافعي قال وفي كتابي عن عبد الله بن محمد بن ناجية حدثنا عمر بن شبة أخبرنا سري بن عياض بن منقذ بن سلمى بن مالك ومالك ابن فاطمة بنت أبي مرثد كناز بن الحصين قال حدثني منقذ بن سلمى عن حديث جده أبي مرثد عن حديث حليفه حمزة بن عبد المطلب رضي الله عنه حديثا مسند إلى النبي صلى الله عليه وسلم قال الزموا هذا الدعاء اللهم إني أسألك باسمك الأعظم ورضوانك الأكبر أخبرنا أبو محمد بن أبي القاسم الدمشقي في كتابة أخبرنا أبو عبد الله محمد بن إبراهيم وأبو محمد عبد الرحمن بن أبي الحسن قالا أخبرنا سهل بن بشر أخبرنا علي بن منير أخبرنا أبو طاهر الذهلي أخبرنا محمد بن علي بن شعيب أخبرنا خالد بن خداش أخبرنا حماد بن زيد عن أبي الزبير عن جابر قال استصرخنا على قتلانا يوم أحد يوم حفر معاوية العين فوجدناهم رطابا يتثنون زاد عبد الرحمن وذلك على رأس أربعين سنة قالا وقال حماد بن زيد وزادني جرير بن حازم عن أيوب فأصاب المر رجل حمزة فطار منها الدم أخرجه الثلاثة * سلمى بضم السين والإمالة وحازم بالحاء المهملة'
WHERE id = 65
  AND content_ar LIKE '(ب د ع) حمزة ابن عبد%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 65;


