BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عبد الله بن مسعود بن غافل بن حبيب بن شمخ بن فار بن مخروم بن صاهلة ابن كاهل بن الحارث بن تميم بن سعد بن هذيل بن مدركة بن إلياس بن مضر أبو عبد الرحمن الهذلي حليف بني زهرة كان أبوه مسعود قد حالف في الجاهلية عبد بن الحارث بن زهرة وأم عبد الله بن مسعود أم عبد بنت عبد ود بن سواء من هذيل أيضا كان إسلامه قديما أول الإسلام حين أسلم سعيد بن زيد وزوجته فاطمة بنت الخطاب وذلك قبل إسلام عمر بن الخطاب بزمان روى الأعمش عن القاسم بن عبد الرحمن عن أبيه قال قال عبد الله لقد رأيتني سادس ستة ما على ظهر الأرض مسلم غيرنا وكان سبب إسلامه ما أخبرنا به أبو الفضل الطبري الفقيه بإسناده إلى أبي يعلى أحمد بن علي قال حدثنا المعلى بن مهدي حدثنا أبو عوانة عن عاصم بن بهدلة عن دد عن عبد الله بن مسعود قال كنت غلاما يافعا في غنم لعقبة بن أبي معيط أرعاها فأتى النبي صلى الله عليه وسلم ومعه أبو بكر فقال يا غلام هل معك من لبن فقلت نعم ولكني مؤتمن فقال ائتني بشاة لم ينز عليها الفحل فأتيته بعناق أو جذعة فاعتقلها رسول الله صلى الله عليه وسلم فجعل يمسح الضرع ويدعو حتى أنزلت فأتاه أبو بكر بصحوة فاحتلب فيها ثم قال لأبي بكر اشرب فشرب أبو بكر ثم شرب النبي صلى الله عليه وسلم بعده ثم قال للضرع اقلص فقلص فعاد كما كان ثم أتيت فقلت يا رسول الله علمني من هذا الكلام أو من هذا القرآن فمسح رأسي وقال إنك غلام معلم قال فلقد أخذت منه سبعين سورة ما نازعني فيها بشر وهو أول من جهر بالقرآن بمكة أخبرنا عبيد الله بن أحمد بإسناده عن يونس بن بكير عن محمد بن إسحاق قال حدثني يحيى بن عروة بن الزبير عن أبيه قال كان أول من جهر بالقرآن بمكة بعد رسول الله صلى الله عليه وسلم عبد الله بن مسعود اجتمع يوما أصحاب رسول الله صلى
الله عليه وسلم فقالوا والله ما سمعت قريش هذا القرآن يجهر لها به قط فمن رجل يسمعهم فقال عبد الله بن مسعود أنا فقالوا إنا نخشاهم عليك إنما نريد رجلا له عشيرة تمنعه من القوم إن أرادوه فقال دعوني فإن الله سيمنعني فغدا عبد الله حتى أتى المقام في الضحى وقريش في أنديتها حتى قام عند المقام فقال رافعا صوته بسم الله الرحمن الرحيم الرحمن علم القرآن فاستقبلها فقرأ بها فتأملوا فجعلوا يقولون ما يقول ابن أم عبد ثم قالوا إنه ليتلو بعض ما جاء به محمد فقاموا فجعلوا يضربون في وجهه وجعل يقرأ حتى بلغ منها ما شاء الله أن يبلغ ثم انصرف إلى أصحابه وقد أثروا بوجهه فقالوا هذا الذي خشينا عليك فقال ما كان أعداء الله قط أهون علي منهم الآن ولئن شئتم غاديتهم بمثلها غدا قالوا حسبك قد أسمعتهم ما يكرهون ولما أسلم عبد الله أخذه رسول الله صلى الله عليه وسلم إليه وكان يخدمه وقال له إذنك علي أن تسمع سوادي ويرفع الحجاب فكان يلج عليه ويلبسه نعليه ويمشي معه وأمامه ويستره إذا اغتسل ويوقظه إذا نام وكان يعرف في الصحابة بصاحب السواد والسواك أخبرنا أبو الفرج الثقفي أخبرنا أبو علي الحداد وأنا حاضر أسمع أخبرنا أبو نعيم أخبرنا عبد الله ابن جعفر الجابري حدثنا أحمد بن محمد بن المثنى حدثنا علي بن زياد الأحمر حدثنا ابن إدريس وحفص عن الحسن بن عبيد الله عن إبراهيم بن سويد عن عبد الرحمن ابن يزيد عن عبد الله قال قال لي رسول الله صلى الله عليه وسلم إذنك علي أن يرفع الحجاب وتسمع سوادي حتى أنهاك وهاجر الهجرتين جميعا إلى الحبشة وإلى المدينة وصلى القبلتين وشهد بدرا وأحدا والخندق وبيعة الرضوان وسائر المشاهد مع رسول الله صلى الله عليه وسلم وشهد اليرموك بعد النبي صلى الله عليه وسلم وهو الذي أجهز على أبي جهل وشهد له رسول الله صلى الله عليه وسلم بالجنة وروي عن النبي صلى الله عليه وسلم روى عنه من الصحابة ابن عباس وابن عمر وأبو موسى وعمران بن حصين وابن الزبير وجابر وأنس وأبو سعيد وأبو هريرة وأبو رافع وغيرهم وروى عنه من التابعين علقمة وأبو وائل والأسود ومسروق وعبيدة وقيس بن أبي حازم وغيرهم أخبرنا أبو منصور مسلم بن علي بن محمد الموصلي العدل قال أخبرنا أبو البركات محمد بن محمد بن خميس أخبرنا أبو نصر أحمد بن عبد الباقي ابن طوق أخبرنا أبو القاسم نصر بن أحمد بن الخليل المرجي أخبرنا أحمد بن علي ابن المثنى حدثنا أبو خيثمة حدثنا جرير عن مغيرة عن أبي رزين قال قال ابن مسعود قال لي رسول الله صلى الله عليه وسلم اقرأ علي سورة النساء قال قلت أقرأ عليك وعليك أنزل قال إني أحب أن أسمعه من غيري فقرأت عليه حتى بلغت فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدا إلى آخر الآية فاضت عيناه صلى الله عليه وسلم أخبرنا أبو البركات الحسن بن محمد بن الحسن بن هبة الله الدمشقي أخبرنا أبو العشائر محمد بن خليل بن فارس القيسي أخبرنا أبو القاسم علي بن محمد بن علي المصيصي أخبرنا أبو محمد عبد الرحمن بن عثمان بن القاسم بن أبي نصر أخبرنا أبو الحسن خيثمة بن سليمان بن حيدرة الأطرابلسي حدثنا أبو عبيدة السري بن يحيى بالكوفة حدثنا قبيصة بن عقبة حدثنا سفيان الثوري عن عبد الملك بن عمير عن مولى لربعي عن ربعي عن حذيفة قال قال رسول الله صلى الله عليه وسلم وتمسكوا بعهد ابن أم عبد وقد رواه سلمة بن كهيل عن أبي الزعراء عن ابن مسعود وأخبرنا إسماعيل بن علي بن عبيد الله وغير واحد بإسنادهم إلى محمد بن عيسى قال حدثنا أبو كريب حدثنا إبراهيم بن يوسف بن أبي إسحاق عن أبيه عن أبي إسحاق عن أبي الأسود بن يزيد أنه سمع أبا موسى يقول لقد قدمت أنا وأخي من اليمن وما نرى إلا أن عبد الله بن مسعود رجل من أهل بيت النبي صلى الله عليه وسلم لما نرى من دخوله ودخول أمه على النبي صلى الله عليه وسلم قال وأخبرنا محمد ابن عيسى حدثنا محمد بن بشار حدثنا عبد الرحمن بن مهدي حدثنا إسرائيل عن أبي إسحاق عن عبد الرحمن بن يزيد قال أتينا حذيفة فقلنا حدثنا بأقرب الناس من رسول الله صلى الله عليه وسلم هديا ودلا فنأخذ عنه ونسمع منه قال كان أقرب الناس هديا ودلا وسمتا برسول الله صلى الله عليه وسلم ابن مسعود ولقد علم المحفوظون من أصحاب محمد أن ابن أم عبد هو من أقربهم إلى الله زلفى قال وأخبرنا محمد بن عيسى قال حدثنا عبد الله بن عبد الرحمن حدثنا صاعد الحراني حدثنا زهير عن منصور عن أبي إسحاق عن الحارث عن علي رضي الله عنه قال قال رسول الله صلى الله عليه وسلم لو كنت مؤمرا أحدا من غير مشورة لأمرت ابن أم عبد ومن مناقبه أنه بعد وفاة رسول الله صلى الله عليه وسلم شهد المشاهد العظيمة منها أنه شهد اليرموك بالشام وكان على النفل وسيره عمر بن الخطاب رضي الله عنه إلى الكوفة وكتب إلى أهل الكوفة إني قد بعثت عمار بن ياسر أميرا وعبد الله بن مسعود معلما ووزيرا وهما من النجباء من أصحاب رسول الله صلى الله عليه وسلم من أهل بدر فاقتدوا بهما وأطيعوا واسمعوا قولهما وقد آثرتكم بعبد الله على نفسي أخبرنا ابن أبي حبة بإسناده عن عبد الله بن أحمد حدثني أبي حدثنا محمد بن فضيل حدثنا مغيرة عن أم موسى قالت سمعت عليا يقول أمر النبي صلى الله عليه وسلم ابن مسعود فصعد على شجرة يأتيه منها بشئ فنظر أصحابه إلى ساق عبد الله فضحكوا من حموشة ساقيه فقال رسول الله صلى الله عليه وسلم ما تضحكون لرجل عبد الله أثقل في الميزان يوم القيامة من أحد وأخبرنا عمر بن محمد بن طبرزد إجازة أخبرنا أبو البركات الأنماطي إجازة إن لم يكن سماعا أخبرنا أبو طاهر وأبو الفضل الباقلانيان قالا أخبرنا أبو القاسم الواعظ أخبرنا أبو علي الصواف حدثنا محمد بن عثمان بن أبي شيبة حدثنا محمد بن عبد الله بن نمير حدثنا أبي عن الأعمش عن حبة ابن جوين عن علي قال كنا عنده جلوسا فقالوا ما رأينا رجلا أحسن خلقا ولا أرفق تعليما ولا أحسن مجالسة لا أشد ورعا من ابن مسعود قال علي أنشدكم الله أهو الصدق من قلوبكم قالوا نعم قال اللهم أشهد أني أقول مثل ما قالوا وأفضل قال أبو وائل لما شق عثمان رضي الله عنه المصاحف بلغ ذلك عبد الله فقال لقد علم أصحاب محمد أني أعلمهم بكتاب الله وما أنا بخيرهم ولو إني أعلم أن أحدا أعلم بكتاب الله مني تبلغنيه الإبل لأتيته فقال أبو وائل فقمت إلى الحلق أسمع ما يقولون فما سمعت أحدا من أصحاب محمد ينكر ذلك عليه وقال زيد بن وهب إني لجالس مع عمر إذ جاءه ابن مسعود يكاد الجلوس يوارونه من قصره فضحك عمر حين رآه فجعل يكلم عمر ويضاحكه وهو قائم ثم ولى فأتبعه عمر بصرة حتى توارى فقال كيف ملئ علما وقال عبيد الله ابن عبد الله كان عبد الله إذا هدأت العيون قام فسمعت له دويا كدوي النحل حتى يصبح وقال سلمة بن تمام لقي رجل ابن مسعود فقال لا تعدم حالما مذكرا رأيتك البارحة ورأيت النبي صلى الله عليه وسلم على منبر مرتفع وأنت دونه وهو يقول يا ابن مسعود هلم إلي فلقد جفيت بعدي فقال الله لأنت رأيت هذا قال نعم قال فعزمت أن تخرج من المدينة حتى تصلي علي فما لبث أياما حتى مات وقال أبو طيبة مرض عبد الله فعاده عثمان بن عفان فقال ما تشتكي قال ذنوبي قال فما تشتهي قال رحمة ربي قال ألا آمر لك بطبيب قال الطبيب أمرضني قال ألا آمر لك بعطاء قال لا حاجة لي فيه قال يكون لبناتك قال أتخشى على بناتي الفقر إني أمرت بناتي؟ ن يقرآن كل ليلة سورة الواقعة أني سمعت رسول الله صلى الله عليه وسلم يقول من 
قرأ الواقعة كل ليلة لم تصبه فاقه أبدا وإنما قال له عثمان ألا آمر لك بعطائك لأنه كان قد حبسه عنه سنتين فلما توفي أرسله إلى الزبير فدفعه إلى ورثته وقيل بل كان عبد الله ترك العطاء استغناء عنه وفعل غيره كذلك وروى الأعمش عن زيد بن وهب قال لما بعث عثمان إلى عبد الله بن مسعود يأمره بالقدوم عليه بالمدينة وكان بالكوفة اجتمع الناس عليه فقالوا أقم ونحن نمنعك أن يصل إليك شئ تكرهه فقال عبد الله أن له علي حق الطاعة وإنها ستكون أمور وفتن فلا أحب أن أكون أول من فتحها فرد الناس وخرج إليه وتوفي ابن مسعود بالمدينة سنة اثنتين وثلاثين وأوصى إلى الزبير رضي الله عنهما ودفن بالبقيع وصلى عليه عثمان وقيل صلى عليه عمار بن ياسر وقيل صلى عليه الزبير ودفنه ليلا أوصى بذلك وقيل لم يعلم عثمان رضي الله عنه بدفنه فعاتب الزبير على ذلك وكان عمره يوم توفي بضعا وستين سنة وقبل بل توفي سنة ثلاث وثلاثين والأول أكثر ولما مات ابن مسعود نعي إلى أبي الدرداء فقال ما ترك بعده مثله أخرجه الثلاثة'
WHERE id = 66
  AND content_ar LIKE '(ب د ع) عبد الله بن %'
  AND source_codes IS NULL;

