-- id=70  صهيب بن سنان الرومي
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 70;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'صهيب بن سنان بن مالك بن عبد عمرو بن عقيل بن عامر بن جندلة بن جذيمة بن كعب بن سعد بن أسلم بن أوس مناة بن النمر بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار الربعي النمري كذا نسبه الكلبي وأبو نعيم وقال الواقدي هو صهيب بن سنان بن خالد بن عبد عمرو بن عقيل بن كعب بن سعد وقال ابن إسحاق صهيب بن سنان بن خالد بن عبد عمرو بن طفيل بن عامر بن جندلة بن سعد بن خزيمة بن كعب بن سعد فجعل طفيلا بدل عقيل وجعل خزيمة بدل جذيمة وهو من النمر بن قاسط وأمه سلمى بنت قعيد بن مهيص بن خزاعي بن مازن ابن مالك بن عمرو بن تميم كنيته أبو يحيى كناه بها رسول الله صلى الله عليه وسلم وإنما قيل له الرومي لأن الروم سبوه صغيرا وكان أبوه وعمه عاملين لكسرى على الأبلة
وكانت منازلهم على دجلة عند الموصل وقيل كانوا على الفرات من أرض الجزيرة فأغارت الروم عليهم فأخذت صهيبا وهو صغير فنشأ بالروم فصار ألكن فابتاعته منهم كلب ثم قدموا به مكة فاشتراه عبد الله بن جدعان التيمي منهم فأعتقه فأقام معه إلى أن هلك عبد الله بن جدعان وقال أهل صهيب وولده ومصعب الزبيري إنه هرب من الروم لما كبر وعقل فقدم مكة فحالف ابن جدعان وأقام معه إلى أن هلك ولما بعث رسول الله صلى الله عليه وسلم أسلم وكان من السابقين إلى الإسلام قال الواقدي أسلم صهيب وعمار في يوم واحد وكان إسلامهما بعد بضعة وثلاثين رجلا وكان من المستضعفين بمكة الذين عذبوا أخبرنا أبو منصور بن مكارم بن أحمد ابن سعد بإسناده إلى أبي زكرياء يزيد بن إياس قال وكان اشتراه عبد الله بن جدعان يعني صهيبا من كلب بمكة وكانت كلب اشترته من الروم فأعتقه وأسلم صهيب ورسول الله صلى الله عليه وسلم في دار الأرقم بعد بضعة وثلاثين رجلا وكان من المستضعفين بمكة المعذبين في الله عز وجل وقدم في آخر الناس في الهجرة إلى المدينة على ابن أبي طالب وصهيب وذلك في النصف الأول من ربيع الأول ورسول الله صلى الله عليه وسلم بقباء لم يرم بعد وآخى رسول الله صلى الله عليه وسلم بينه وبين الحارث بن الصمة ولما هاجر صهيب إلى المدينة تبعه نفر من المشركين فنثل كنانته وقال لهم يا معشر قريش تعلمون أني من أرماكم ووالله لا تصلون إلي حتى أرميكم بكل سهم معي ثم أضربكم بسيفي ما بقي في يدي منه شئ فإن كنتم تريدون مالي دللتكم عليه قالوا فدلنا على مالك ونخلي عنك فتعاهدوا على ذلك فدلهم عليه ولحق برسول الله صلى الله عليه وسلم فقال له رسول الله صلى الله عليه وسلم ربح البيع أبا يحيى فأنزل الله عز وجل ومن الناس من يشري نفسه ابتغاء مرضات الله والله رؤوف بالعباد وشهد صهيب بدرا وأحدا والخندق والمشاهد كلها مع رسول الله صلى الله عليه وسلم أخبرنا أبو منصور بن مكارم بإسناده عن أبي زكرياء أخبرنا إسحاق بن الحسن الحربي حدثنا أبو حذيفة موسى بن مسعود حدثنا عمارة بن ذادان عن ثابت عن أنس قال قال رسول الله صلى الله عليه وسلم السباق أربعة أنا سابق العرب وصهيب سابق الروم وسلمان سابق فارس وبلال سابق الحبش قال وأخبرنا أبو زكرياء أخبرنا أحمد بن عبد الصمد حدثنا علي بن الحسين حدثنا عفيف حدثنا سفيان عن منصور عن مجاهد قال أول من أظهر إسلامه سبعة النبي صلى الله عليه وسلم وأبو بكر وبلال وصهيب وخباب وعمار بن ياسر وسمية أم عمار رضي الله عنهم أجمعين فأما النبي صلى الله عليه وسلم فمنعه الله وأما أبو بكر فمنعه قومه وأما الآخرون فأخذوا وألبسوا أدراع الحديد ثم أصهروا في الشمس أخبرنا أبو جعفر بن المبارك ابن أحمد بن زريق الواسطي إمام الجامع بها أخبرنا أبو السعادات المبارك بن الحسين بن عبد الوهاب أخبركم أبو الفتح منصور بن الحسن بن أبي القاسم الشاشي فاعترف به قلت له أخبركم أبو بكر بن منصور بن خلف المقري أخبرنا أبو الحسين عبد الله بن أحمد بن علي الحنبلي أخبرنا أبو القاسم عبد الله بن إبراهيم ابن بالويه حدثنا عمران بن موسى حدثنا هدية بن خالد حدثنا حماد بن سلمة عن ثابت عن عبد الرحمن بن أبي ليلى عن صهيب أن رسول الله صلى الله عليه وسلم قال إذا دخل أهل الجنة الجنة وأهل النار النار نادى مناديا أهل الجنة إن لكم عند الله عز وجل موعدا يريد أن ينجزكموه فيقولون ما هو ألم يثقل موازيننا ويبيض وجوهنا ويدخلنا الجنة ويخرجنا من النار فيكشف لهم الحجاب فينظرون إلى الله تبارك وتعالى فما شئ أعطوه أحب إليهم من النظر إليه وهي الزيادة وروى عنه ابن عمر أنه قال مررت برسول الله صلى الله عليه وسلم وهو يصلي فسلمت عليه فرد على إشارة بإصبعه أخبرنا أبو إسحاق إبراهيم بن محمد بن مهران الفقيه وغيره بإسنادهم إلى أبي عيسى محمد بن عيسى حدثنا محمد بن إسماعيل الواسطي حدثنا أبو فروة يزيد بن سنان عن أبي المبارك عن صهيب قال قال رسول الله صلى الله عليه وسلم ما آمن بالقرآن من استحل محارمه وكان فيه مع فضله وعلو درجته مداعبة وحسن خلق روى عنه أنه قال جئت النبي صلى الله عليه وسلم وهو نازل بقباء وبين أيديهم رطب وتمر وأنا أرمد فأكلت فقال النبي صلى الله عليه وسلم أتأكل التمر وأنت أرمد فقلت إنما آكل على شق عيني الصحيحة فضحك رسول الله صلى الله عليه وسلم حتى بدت نواجذه وكان في لسانه عجمة شديدة وروى زيد بن أسلم عن أبيه قال خرجت مع عمر حتى دخل على صهيب حائطا له بالعالية فلما رآه صهيب قال يناس يناس فقال عمر ماله لا أبا له يدعو بالناس فقلت إنما يدعو غلاما له اسمه يحنس وإنما قال ذلك لعقده في لسانه فقال له عمر ما فيك شئ أعيبه يا صهيب إلا ثلاث خصال لولاهن ما قدمت عليك أحدا أراك تنتسب عربيا ولسانك أعجمي وتكتني بأبي يحيى اسم نبي وتبذر مالك فقال أما تبذيري مالي فما 
أنفقه إلا في حقه وأما اكتنائي بأبي يحيى فإن رسول الله صلى الله عليه وسلم كناني بأبي يحيى فلن أتركها وأما انتمائي إلى العرب فإن الروم سبتني صغيرا فأخذت لسانهم وأنا رجل من النمر بن قاسط ولو انفلقت عني روثة لانتميت إليها وكان عمر بن الخطاب رضي الله عنه محبا لصهيب حسن الظن فيه حتى إنه لما ضرب أوصي أن يصلي عليه صهيب وأن يصلي بجماعة المسلمين ثلاثا حتى تتفق أهل الشورى على من يستخلف وتوفي صهيب بالمدينة سنة ثمان وثلاثين في شوال وقيل سنة تسع وثلاثين وهو ابن ثلاث وسبعين سنة وقيل ابن سبعين سنة ودفن بالمدينة وكان أحمر شديد الحمرة ليس بالطويل ولا بالقصير وهو إلى القصر أقرب كثير شعر الرأس أخرجه الثلاثة'
WHERE id = 70
  AND content_ar LIKE '(ب د ع) صهيب بن سنان%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 70;


