UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عثمان بن مظعون بن حبيب بن وهب ابن حذافة بن جمح بن عمرو بن هصيص بن كعب بن لوى بن غالب القرشي الجمحي يكنى أبا السائب أمه سخيلة بنت العنبس بن أهبان بن حذافة بن جمح وهي أم السائب وعبد الله ابني مظعون أسلم أول الإسلام قال ابن إسحاق أسلم عثمان بن مظعون بعد ثلاثة عشر رجلا وهاجر إلى الحبشة هو وابنه السائب الهجرة الأولى مع جماعة من المسلمين فبلغهم وهم بالحبشة أن قريشا قد أسلمت فعادوا أخبرنا أبو جعفر بن السمين بإسناده إلى يونس بن بكير عن ابن إسحاق قال فلما بلغ من بالحبشة سجود أهل مكة مع رسول الله صلى الله عليه وسلم أقبلوا ومن شاء الله منهم وهم يرون أنهم قد تابعوا النبي صلى الله عليه وسلم فلما دنوا من مكة بلغهم الأمر فثقل عليهم أن يرجعوا وتخوفوا أن يدخلوا مكة بغير جوار فمكثوا حتى دخل كل رجل منهم بجوار من بعض أهل مكة وقدم عثمان بن مظعون بجوار الوليد بن المغيرة قال ابن إسحاق فحدثني صالح بن إبراهيم بن عبد الرحمن بن عوف عن أبيه عمن حدثه قال لما رأى عثمان ما يلقى رسول الله صلى الله عليه وسلم وأصحابه من الأذى وهو يغدو ويروح بأمان الوليد بن المغيرة قال عثمان والله إن غدوي ورواحي آمنا بجوار رجل من أهل الشرك وأصحابي وأهل بيتي يلقون البلاء والأذى في الله مالا يصيبني لنقص شديد في نفسي فمضى إلى الوليد بن المغيرة فقال يا أبا عبد شمس وفت ذمتك قد كنت في جوارك وقد أحببت
أن أخرج منه إلى رسول الله صلى الله عليه وسلم فلي به وبأصحابه أسوة فقال الوليد فلعلك يا ابن أخي أوذيت أو انتهكت قال لا ولكن أرضى بجوار الله ولا أريد أن أستجير بغيره قال فانطلق إلى المسجد فاردد على جواري علانية كما أجرتك علانية فقال انطلق فخرجا حتى أتيا المسجد فقال الوليد هذا عثمان بن مظعون قد جاء ليرد علي جواري فقال عثمان صدق وقد وجدته وفيا كريم الجوار وقد أحببت أن لا أستجير بغير الله عز وجل وقد رددت عليه جواره ثم انصرف عثمان بن مظعون ولبيد بن ربيعة بن جعفر بن كلاب القيسي في مجلس قريش فجلس معهم عثمان فقال لبيد وهو ينشدهم * ألا كل شئ ما خلى الله باطل * فقال عثمان صدقت قال لبيد * وكل نعيم لا محالة زائل * فقال عثمان كذبت فالتفت القوم إليه فقالوا للبيد أعد علينا فأعاد لبيد وأعاد له عثمان بتكذيبه مرة وبتصديقه مرة وإنما يعني عثمان إذا قال كذبت يعني نعيم الجنة لا يزول فقال لبيد والله يا معشر قريش ما كانت مجالسكم هكذا فقام سفيه منهم إلى عثمان بن مظعون فلطم عينه فاخضرت فقال له من حوله والله يا عثمان لقد كنت في ذمة منيعة وكانت عينك غنية عما لقيت فقال عثمان جوار الله آمن وأعز وعيني الصحيحة فقيرة إلى ما لقيت أختها ولي برسول الله صلى الله عليه وسلم وبمن آمن معه أسوة فقال الوليد هل لك في جواري فقال عثمان لا أرب لي في جوار أحد إلا في جوار الله ثم هاجر عثمان إلى المدينة وشهد بدرا وكان من أشد الناس اجتهادا في العبادة يصوم النهار ويقوم الليل ويجتنب الشهوات ويعتزل النساء واستأذن رسول الله صلى الله عليه وسلم في التبتل والاختصاء فنهاه عن ذلك وهو ممن حرم الخمر على نفسه وقال لا أشرب شرابا يذهب عقلي ويضحك بي من هو أدنى مني وهو أول رجل مات بالمدينة من المهاجرين مات سنة اثنتين من الهجرة قيل توفي بعد اثنين وعشرين شهرا بعد شهوده بدرا وهو أول من دفن بالبقيع أخبرنا إبراهيم بن محمد بن مهران وغيره قالوا بإسنادهم إلى محمد بن عيسى قال حدثنا محمد بن بشار حدثنا عبد الرحمن بن مهدي حدثنا سفيان عن عاصم بن عبيد الله عن القاسم بن محمد عن عائشة أن النبي صلى الله عليه وسلم قبل عثمان بن مظعون وهو ميت وهو يبكي وعيناه تهراقان ولما توفي إبراهيم ابن رسول الله صلى الله عليه وسلم قال رسول الله صلى الله عليه وسلم الحق بالسلف الصالح عثمان بن مظعون وروى أن النبي صلى الله عليه وسلم قال ذاك لابنته زينب 
﵍ وأعلم النبي صلى الله عليه وسلم على قبره بحجر وكان يزوره وروى ابن عباس أن النبي صلى الله عليه وسلم دخل على عثمان بن مظعون حين مات فانكب عليه ورفع رأسه ثم حنى الثانية ثم حنى الثانية ثم رفع رأسه وله شهيق وقال اذهب عند أبا السائب خرجت منها ولم تلبس منها بشئ وروى يوسف بن مهران عن ابن عباس قال لما مات عثمان بن مظعون قالت امرأته هينا لك الجنة فنظر رسول الله صلى الله عليه وسلم نظر المغضب وقال وما يدريك فقالت يا رسول الله فارسك وصاحبك فقال رسول الله صلى الله عليه وسلم أني رسول الله وما أدري ما يفعل بي واختلف الناس في المرأة التي قال لها رسول الله صلى الله عليه وسلم هذا فقيل كانت أم السائب زوجته وقيل أم العلاء الأنصارية وكان نزل عليها وقيل كانت أم خارجة بنت زيد وقالت امرأته ترثيه

يا عين جودي بدمع غير ممنونعلى رزية عثمان بن مظعونعلى امرئ بات في رضوان خالقهطوبى له من فقيد الشخص مدفونطاب البقيع له سكنى وغرقدهوأشرقت أرضه من بعد تعيينوأورث القلب حزنا لا انقطاع لهحتى الممات فما ترقى له شوني
وقالت أم العلاء رأيت لعثمان بن مظعون عينا تجري فجئت رسول الله صلى الله عليه وسلم فأخبرته فقال ذاك عمله أخرجه الثلاثة'
WHERE id = 72
  AND content_ar LIKE '(ب د ع) عثمان بن مظع%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 72;


-- الخطوة 2 (v2: LIKE بالبداية + معاملة مستقلة لكل صف) - دفعة 23/31 (2 صفوف)

-- id=73  المقداد بن عمرو (ابن الأسود)
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 73;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'المقداد بن عمرو بن ثعلبة بن مالك بن ربيعة بن ثمامة بن مطرود بن عمرو بن سعد بن دهير بن لؤي بن ثعلبة بن مالك بن الشريد بن أبي أهون بن قاس بن دريم بن القين بن أهون بن بهراء بن عمرو بن الحاف ابن قضاعة البهراوي المعروف بالمقداد بن الأسود وهذا الأسود الذي ينسب إليه هو الأسود بن عبد يغوث الزهري وإنما نسب إليه لأن المقداد حالفه فتبناه الأسود فنسب إليه ويقال له أيضا المقداد الكندي وإنما قيل له ذلك لأنه أصاب دما في بهراء فهرب منهم إلى كنده فحالفهم ثم أصاب فيهم دما فهرب إلى مكة فحالف الأسود بن عبد يغوث وقال أحمد بن صالح المصري هو حضرمي وحالف أبوه كنده فنسب إليها وحالف هو الأسود بن عبد يغوث فنسب إليه والصحيح أنه بهراوي كنيته أبو معبد وقيل أبو الأسود وهو قديم الإسلام من السابقين وهاجر إلى أرض الحبشة ثم عاد إلى مكة فلم يقدر على الهجرة إلى المدينة لما هاجر إليها رسول الله صلى الله عليه وسلم فبقي إلى أن بعث رسول الله صلى الله عليه وسلم عبيدة بن الحارث في سرية فلقوا جمعا من المشركين عليهم عكرمة بن أبي جهل وكان المقداد وعتبة بن غزوان قد خرجا مع المشركين ليتوصلا إلى المسلمين فتواقفت الطائفتان ولم يكن قتال فانحاز المقداد وعتبة إلى المسلمين أخبرنا أبو جعفر بن السمين بإسناده عن يونس بن بكير عن ابن إسحاق في تسمية من هاجر إلى الحبشة من بني زهرة ومن بهراء المقداد بن عمرو وكان يقال له المقداد بن الأسود بن عبد يغوث بن وهب بن عبد مناف بن زهرة وذلك أنه كان تبناه وحالفه وشهد بدرا أيضا وله فيها مقام مشهور وبهذا الإسناد عن ابن إسحاق قال أتى رسول الله صلى الله عليه وسلم لما سار إلى بدر الخبر عن قريش بمسيرهم ليمنعوا عيرهم فاستشار رسول الله صلى الله عليه وسلم الناس
فقال أبو بكر فأحسن وقال عمر فأحسن ثم قام المقداد بن عمرو فقال يا رسول الله امض لما أمرت به فنحن معك والله لا نقول لك كما قالت بنو إسرائيل لموسى اذهب أنت وربك فقاتلا إنا هاهنا قاعدون ولكن اذهب أنت وربك فقاتلا إنا معكما مقاتلون فوالذي بعثك بالحق نبيا لو سرت بنا إلى برك الغماد لجالدنا معك من دونه حتى تبلغه فقال له رسول الله صلى الله عليه وسلم خيرا ودعا له قيل لم يكن ببدر صاحب فرس غير المقداد وقيل غيره والله أعلم وكان المقداد من أول من أظهر الإسلام بمكة قال ابن مسعود أول من أظهر الإسلام بمكة سبعة منهم المقداد وشهد أحدا أيضا والمشاهد كلها مع رسول الله صلى الله عليه وسلم ومناقبه كثيرة أخبرنا غير واحد بإسنادهم عن أبي عيسى الترمذي قال حدثنا إسماعيل بن موسى الفزاري ابن بنت السدي حدثنا شريك عن أبي ربيعة عن ابن بريدة عن أبيه قال قال رسول الله صلى الله عليه وسلم إن الله عز وجل أمرني بحب أربعة وأخبرني أنه يحبهم قيل يا رسول الله سمهم لنا قال علي منهم يقول ذلك ثلاثا وأبو ذر والمقداد وسلمان وروي على بن أبي طالب عن النبي صلى الله عليه وسلم أنه قال لم يكن نبي إلا أعطي سبعة نجباء وزراء ورفقاء وإني أعطيت أربعة عشر حمزة وجعفر وأبو بكر وعمر وعلي والحسن والحسين وابن مسعود وسلمان وعمار وحذيفة وأبو ذر والمقداد وبلال وشهد المقداد فتح مصر روى عن النبي صلى الله عليه وسلم وروى عنه من الصحابة علي وابن عباس والمستورد بن شداد وطارق بن شهاب وغيرهم ومن التابعين عبد الرحمن بن أبي ليلى وميمون بن أبي شبيب وعبيد الله بن عدي بن الخيار وجبير بن نفير وغيرهم أخبرنا إبراهيم بن محمد الفقيه وغيره بإسنادهم إلى محمد بن عيسى قال حدثنا سويد بن نصر حدثنا ابن المبارك حدثنا عبد الرحمن بن يزيد بن جابر حدثني سليم بن عامر حدثنا المقداد صاحب رسول الله صلى الله عليه وسلم قال سمعت رسول الله صلى الله عليه وسلم يقول إذا كان يوم القيامة أدنيت الشمس من العباد حتى تكون قيد ميل أو اثنين قال سليم لا أدري أي الميلين عنى أمسافة الأرض أم الميل الذي تكحل به العين قال فتصهرهم الشمس فيكونون في المعرق كقدر أعمالهم فمنهم من يأخذه إلى عقبيه ومنهم من يأخذه إلى ركبتيه ومنهم من يأخذه إلى حقويه ومنهم من يلجمه إلجاما فرأيت رسول الله صلى الله عليه وسلم يشير بيده إلى فيه أي يلجمه إلجاما أخبرنا عبد الله بن أحمد بن محمد بن عبد القاهر 
الخطيب قال أخبرنا أبو محمد جعفر بن أحمد السراج أنبأنا علي بن المحسن التنوخي حدثنا أبو عمر بن حيويه الخزاز حدثنا أبو الحسين العباس بن المغيرة حدثنا أبو نصر محمد بن موسى بن هارون الطوسي حدثنا محمد بن سعد عن الواقدي عن موسى بن يعقوب عن عمته عن أمها أن المقداد فتق بطنه فخرج منه الشحم وكانت وفاته بالمدينة في خلافة عثمان ومات بأرض له بالجرف وحمل إلى المدينة وأوصى إلى الزبير ابن العوام وكان عمره سبعين سنة وكان رجلا ضخما قاله منصور عن إبراهيم عن همام بن الحارث أخرجه الثلاثة'
WHERE id = 73
  AND content_ar LIKE '(ب د ع) المقداد بن ع%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 73;

-- id=74  عامر بن فهيرة
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 74;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عامر بن فهيرة مولى أبي بكر الصديق يكنى أبا عمرو وكان مولدا من مولدي الأزد أسود اللون مملوكا للطفيل بن عبد الله بن سخبرة أخي عائشة لأمها وكان من السابقين إلى الإسلام قبل أن يدخل رسول الله صلى الله عليه وسلم دار الأرقم أسلم وهو مملوك وكان حسن الإسلام وعذب في الله

فاشتراه أبو بكر فأعتقه ولما خرج رسول الله صلى الله عليه وسلم وأبو بكر إلى الغار بثور مهاجرين أمر أبو بكر مولاه عامر بن فهيرة أن يروح بغنم أبي بكر عليهما وكان يرعاها فكان عامر يرعى في رعيان أهل مكة فإذا أمسى أراح عليهم غنم أبي بكر فاحتلباها وإذا غدا عبد الله بن أبي بكر من عندهما اتبع عامر بن فهيرة أثره بالغنم حتى يعفي عليه فلما سار النبي صلى الله عليه وسلم وأبو بكر من الغار هاجر معهما فأردفه أبو بكر خلفه ومعهم دليلهم من بني الديل وهو مشرك ولما قدم رسول الله صلى الله عليه وسلم المدينة اشتكى أصحابه فاشتكى أبو بكر وبلال وعامر بن فهيرة رضي الله عنهم وشهد عامر بدرا وأحدا وقتل يوم بئر معونة سنة أربع من الهجرة وهو ابن أربعين سنة وقال عامر بن الطفيل لرسول الله صلى الله عليه وسلم لما قدم عليه من الرجل الذي لما قتل رأيته رفع بين السماء والأرض حتى رأيت السماء دونه قال هو عامر بن فهيرة أخبرنا به أبو جعفر بن السمين بإسناده إلى يونس بن بكير عن هشام بن عروة أو محمد بن إسحاق عن هشام شك يونس عن أبيه قال قدم عامر بن الطفيل على رسول الله صلى الله عليه وسلم مثله وروى ابن المبارك وعبد الرزاق عن معمر عن الزهري عن عروة قال طلب عامر يومئذ في القتلى فلم يوجد فيرون أن الملائكة دفنته أو رفعته ودعا رسول الله صلى الله عليه وسلم على الذين قتلوا أصحابه ببئر معونة أربعين صباحا حتى نزلت ليس لك من الأمر شئ وقيل نزلت في غير هذا وروى ابن منده بإسناده عن أيوب بن سنان عن محمد بن المنكدر عن جابر عن عامر بن فهيرة قال تزود أبو بكر مع رسول الله صلى الله عليه وسلم في جيش العسرة بنحي من سمن وعكيكة من عسل على ما كنا عليه من الجهد قال أبو نعيم أطهر يعني ابن منده في روايته هذا الحديث غفلته وجهالته فإن عامرا لم يختلف أحد من أهل النقل أنه استشهد يوم بئر معونة وأجمعوا أن جيش العسرة هو غزوة تبوك بينهما ست سنين فمن استشهد ببئر معونة كيف يشهد جيش العسرة وصوابه أنه تزود مع رسول الله صلى الله عليه وسلم في مخرجه إلى الهجرة والحق مع أبي نعيم أخرجه الثلاثة'
WHERE id = 74
  AND content_ar LIKE '(ب د ع) عامر بن فهير%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 74;


